      "lead": "犯错之后需要面对后果，也需要停止用人格羞辱代替处理问题。越骂自己，不等于越负责。",
      "body": "责任要落到发生了什么、影响了谁、自己能补什么。超出控制的结果不能靠继续折磨自己挽回。",
